/// </summary>
[ExtensionOf(classStr(SalesTableInteractionHelper))]
final class AVASalesTableInteractionHelperCls_Extension
{
}

Method.Source:
 /// <summary>
 ///     AVA <c>parmCanCancel</c> method.
 ///     AVA - Schneider 20.02.2024
 /// </summary>
 /// <returns>
 ///     <c>boolean</c> as return value
 /// </returns>
public boolean parmCanCancel()
 {
     boolean     retVal;

     SalesTable  locSalesTable;

     retVal = next parmCanCancel();

     if(retVal == false)
     {
         locSalesTable = this.salesTable;
         if(locSalesTable.SalesType == SalesType::Journal)
         {
             retVal = true;
         }
     }
     return retVal;
 }
